    for f in files:
        data = torch.load(f'{path}/{f}', map_location='cpu', weights_only=False)
        hs = data['hidden_states']
        print(f'{d}/{f}: type={type(hs).__name__}, ', end='')
        if isinstance(hs, torch.Tensor):
            print(f'shape={hs.shape}, dtype={hs.dtype}')
        elif isinstance(hs, dict):
            print(f'keys={list(hs.keys())[:5]}...')
            for k in list(hs.keys())[:2]:
                v = hs[k]
                if isinstance(v, torch.Tensor):
                    print(f'  {k}: shape={v.shape}, dtype={v.dtype}')
        elif isinstance(hs, (list, tuple)):
            print(f'len={len(hs)}, type[0]={type(hs[0]).__name__}')
            if isinstance(hs[0], torch.Tensor):
                print(f'  [0]: shape={hs[0].shape}')
        else:
            print(f'unknown type')
        print(f'  keys: {list(data.keys())}')
